async (state, model) => {
  const query = state.searchQuery || state.messages[state.messages.length - 1]?.content || '';
  const prompt = `Use the web_search skill to search for: ${query}\n\nProvide:
- Top 10 most relevant results
- Brief description of each result
- Relevance score
- URL for each source`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    searchQuery: query,
    searchResults: [
      'https://example.com/result1',
      'https://example.com/result2',
      'https://example.com/result3'
    ],
    messages: [{ role: 'assistant', content: `Search Results: ${result.content}` }]
  };
}

async (state, model) => {
  const urls = state.searchResults.join('\n');
  const prompt = `Use the web_scraping skill to extract content from these URLs:\n${urls}\n\nExtract:
- Main content and articles
- Key facts and data points
- Images and media
- Metadata and publication dates
- Author information`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    scrapedContent: {
      urls: state.searchResults,
      content: result.content.toString(),
      scrapedAt: new Date().toISOString()
    },
    messages: [{ role: 'assistant', content: `Content Scraped: ${result.content}` }]
  };
}

async (state, model) => {
  const content = state.scrapedContent.content || 'No content available';
  const prompt = `Use the data_analysis skill to analyze the scraped content:\n${content}\n\nProvide:
- Key themes and patterns
- Important facts and statistics
- Conflicting information or gaps
- Source reliability assessment
- Trend analysis`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    analysis: result.content.toString(),
    messages: [{ role: 'assistant', content: `Analysis: ${result.content}` }]
  };
}

async (state, model) => {
  const context = `
Search Query: ${state.searchQuery}
Sources: ${state.searchResults.length} URLs
Analysis: ${state.analysis}
`;

  const prompt = `Create a comprehensive research summary:

1. Executive Summary
2. Key Findings (with citations)
3. Detailed Analysis
4. Conclusions and Recommendations
5. Sources and References

Context:${context}`;

  const result = await model.invoke([{ role: 'user', content: prompt }]);

  return {
    messages: [{ role: 'assistant', content: `Research Summary:\n\n${result.content}` }]
  };
}
